package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class ClearRewardChecks {
 private void ticks(GameWorld w,int n){for(int i=0;i<n;i++)w.step(1f/60,0,false,false);}
 private void clear(GameWorld w){while(w.choosingSkill())w.skipLearning();if(w.boss!=null)w.boss.hp=0;w.enemies.clear();w.x=w.exitX()+2;w.y=112;w.vy=0;w.step(1f/60,0,false,false);assertTrue(w.choosingReward());}
 private void upgrade(GameWorld w,GameWorld.BuildPath path){w.mapIndex=4;w.stageComplete=true;assertTrue(w.advanceStage());clear(w);assertTrue(w.chooseBuildReward(path));assertTrue(w.chooseItemReward(0));assertTrue(w.advanceStage());w.enemies.clear();w.spikes.clear();w.blocks.clear();w.blocks.add(new GameWorld.Block(0,0,4500,112));}
 private GameWorld.Enemy target(GameWorld w,float x,float y){GameWorld.Enemy e=new GameWorld.Enemy(x,y,true);e.primaryType=GameWorld.Element.NORMAL;e.hp=e.maxHp=10000;e.timer=1000;w.enemies.add(e);return e;}
 @Test public void everyNormalClearWaitsForOneUniqueToolChoice(){GameWorld w=new GameWorld();clear(w);assertFalse(w.choosingBuildReward());assertFalse(w.advanceStage());GameWorld.Item[] items={w.rewardItem(0),w.rewardItem(1),w.rewardItem(2)};assertTrue(items[0]==GameWorld.Item.MUSCLE||items[0]==GameWorld.Item.GLASSES);assertNotEquals(items[0],items[1]);assertNotEquals(items[1],items[2]);assertNotEquals(items[0],items[2]);ticks(w,400);assertEquals(1,w.mapIndex);assertEquals(items[1],w.rewardItem(1));assertTrue(w.chooseItemReward(1));assertEquals(1,w.itemCount(items[1]));assertFalse(w.chooseItemReward(1));assertTrue(w.advanceStage());assertEquals(2,w.mapIndex);}
 @Test public void bossOffersBuildThenToolAndNothingCanSkipEither(){GameWorld w=new GameWorld();w.mapIndex=4;w.stageComplete=true;w.advanceStage();clear(w);assertTrue(w.choosingBuildReward());assertFalse(w.chooseItemReward(0));assertFalse(w.advanceStage());assertTrue(w.chooseBuildReward(GameWorld.BuildPath.DRAGON));assertEquals(1,w.buildRank(GameWorld.BuildPath.DRAGON));assertFalse(w.chooseBuildReward(GameWorld.BuildPath.FIRE));assertTrue(w.choosingReward());assertTrue(w.chooseItemReward(0));assertTrue(w.advanceStage());assertEquals(2,w.stage);assertEquals(1,w.mapIndex);}
 @Test public void buildAndToolPersistOnRetryWithoutReclaimingRewards(){GameWorld w=new GameWorld();upgrade(w,GameWorld.BuildPath.FIRE);int tools=w.itemCount(GameWorld.Item.MUSCLE)+w.itemCount(GameWorld.Item.GLASSES);w.hp=0;assertTrue(w.retryStage());assertEquals(1,w.buildRank(GameWorld.BuildPath.FIRE));assertEquals(tools,w.itemCount(GameWorld.Item.MUSCLE)+w.itemCount(GameWorld.Item.GLASSES));assertFalse(w.choosingReward());w.restart();assertEquals(0,w.buildRank(GameWorld.BuildPath.FIRE));}
 @Test public void finalBossRewardsComeBeforeEnding(){GameWorld w=new GameWorld();w.stage=3;w.mapIndex=4;w.stageComplete=true;w.advanceStage();clear(w);assertFalse(w.cleared);assertTrue(w.chooseBuildReward(GameWorld.BuildPath.FIRE));assertFalse(w.cleared);assertTrue(w.chooseItemReward(0));assertTrue(w.cleared);assertFalse(w.choosingReward());}
 @Test public void fireExplosionHitsNearbyEnemyOnlyOncePerCastEvenWithEcho(){GameWorld w=new GameWorld();upgrade(w,GameWorld.BuildPath.FIRE);TestWorlds.equip(w,GameWorld.Skill.EMBER);w.setDropSeed(0);w.collectItem(GameWorld.Item.MULTI);target(w,250,112);GameWorld.Enemy raised=target(w,275,180);assertTrue(w.trySkill(0));ticks(w,30);assertTrue(raised.hp<10000);assertEquals(1,w.buildEffects.stream().filter(f->!f.trail).count());ticks(w,80);assertTrue(w.buildEffects.isEmpty());}
 @Test public void dragonSplitsOnceAndNeverRecursively(){GameWorld w=new GameWorld();upgrade(w,GameWorld.BuildPath.DRAGON);TestWorlds.equip(w,GameWorld.Skill.DRAGON);target(w,220,112);target(w,450,112);GameWorld.Enemy raised=target(w,300,175);java.util.Set<GameWorld.SkillShot> children=new java.util.HashSet<>();w.trySkill(0);for(int i=0;i<90;i++){w.step(1f/60,0,false,false);for(GameWorld.SkillShot s:w.skillShots)if(s.secondary)children.add(s);}assertEquals(2,children.size());assertTrue(raised.hp<10000);}
 @Test public void dashGetsTwoChargesAndLeavesOneHitTrails(){GameWorld w=new GameWorld();upgrade(w,GameWorld.BuildPath.DASH);TestWorlds.equip(w,GameWorld.Skill.FLAME_CHARGE);assertEquals(2,w.skillCharges(0));assertTrue(w.trySkill(0));ticks(w,30);assertEquals(1,w.skillCharges(0));assertTrue(w.buildEffects.stream().anyMatch(f->f.trail));assertTrue(w.trySkill(0));ticks(w,30);assertEquals(0,w.skillCharges(0));assertFalse(w.trySkill(0));ticks(w,140);assertEquals(1,w.skillCharges(0));ticks(w,200);assertEquals(2,w.skillCharges(0));}
 @Test public void tmRewardIsStoredWithoutInterruptingClearSelection() throws Exception{GameWorld w=new GameWorld();clear(w);java.lang.reflect.Field f=GameWorld.class.getDeclaredField("rewardItems");f.setAccessible(true);((GameWorld.Item[])f.get(w))[1]=GameWorld.Item.TM;assertTrue(w.chooseItemReward(1));assertFalse(w.tmSelecting);assertEquals(1,w.itemCount(GameWorld.Item.TM));assertTrue(w.advanceStage());assertTrue(w.openTm());}
 @Test public void trailsHitOnceWithoutTriggeringFireExplosionsOrBurn(){GameWorld w=new GameWorld();upgrade(w,GameWorld.BuildPath.FIRE);upgrade(w,GameWorld.BuildPath.DASH);TestWorlds.equip(w,GameWorld.Skill.FLAME_CHARGE);w.trySkill(0);ticks(w,30);GameWorld.BuildEffect trail=w.buildEffects.stream().filter(f->f.trail).findFirst().get();GameWorld.Enemy e=target(w,trail.x+5,112);ticks(w,1);int hp=e.hp;assertTrue(hp<10000);ticks(w,55);assertEquals(hp,e.hp);assertEquals(0,e.burnTime,0);assertEquals(0,w.buildEffects.stream().filter(f->!f.trail).count());}
}
